    /// V20 karakter kimliği: her karakter 1. seviyeden belirgin bir temel profille başlar, seviyesiyle (1-10) nadirliğine göre
    /// büyür. Sıra: can %, hasar %, hız %, kritik şansı, kritik hasarı %, saldırı hızı %, alınan hasar −%, kaçınma,
    /// can çalma, saniyede can yenilenmesi; sonra seviye başına can % ve hasar %.
    pub struct CharBase {
        pub hp: f32, pub dmg: f32, pub speed: f32, pub crit: f32, pub crit_dmg: f32, pub atk_speed: f32,
        pub armor: f32, pub dodge: f32, pub lifesteal: f32, pub regen: f32,
        pub hp_lv: f32, pub dmg_lv: f32,
    }
    pub const CHAR_BASE: [CharBase; 4] = [
        // Kael (sıradan): çevik dövüşçü — hız ve kaçınma
        CharBase { hp: 0.0, dmg: 0.0, speed: 0.10, crit: 0.0, crit_dmg: 0.0, atk_speed: 0.05, armor: 0.0, dodge: 0.06, lifesteal: 0.0, regen: 0.0,
                   hp_lv: 0.03, dmg_lv: 0.03 },
        // Lyra (nadir): kritik ve hız; az can
        CharBase { hp: -0.05, dmg: 0.10, speed: 0.06, crit: 0.06, crit_dmg: 0.25, atk_speed: 0.08, armor: 0.0, dodge: 0.03, lifesteal: 0.0, regen: 0.0,
                   hp_lv: 0.03, dmg_lv: 0.04 },
        // Vex (destansı): tank — çok can, zırh, can yenilenmesi; yavaş
        CharBase { hp: 0.40, dmg: 0.05, speed: -0.06, crit: 0.0, crit_dmg: 0.0, atk_speed: 0.0, armor: 0.12, dodge: 0.0, lifesteal: 0.0, regen: 1.0,
                   hp_lv: 0.06, dmg_lv: 0.03 },
        // Morvath (efsanevi): yüksek hasar, can çalma, saldırı hızı
        CharBase { hp: 0.15, dmg: 0.20, speed: 0.04, crit: 0.04, crit_dmg: 0.15, atk_speed: 0.10, armor: 0.05, dodge: 0.0, lifesteal: 0.04, regen: 0.0,
                   hp_lv: 0.04, dmg_lv: 0.05 },
    ];

    /// Karakterin [lv] seviyesindeki kimlik değerleri (arayüz: "Can +%40" gibi; sıfırlar atlanır)
    pub fn char_stats(i: usize, lv: u32) -> Vec<(&'static str, String)> {
        let c = &CHAR_BASE[i.min(3)];
        let s = lv.max(1).saturating_sub(1) as f32;
        let pct = |v: f32| format!("{}%{}", if v < 0.0 { "−" } else { "+" }, (v.abs() * 100.0).round() as i32);
        let mut out = vec![("Can", pct(c.hp + c.hp_lv * s)), ("Hasar", pct(c.dmg + c.dmg_lv * s))];
        for (k, v) in [("Hız", c.speed), ("Kritik Şansı", c.crit), ("Kritik Hasarı", c.crit_dmg), ("Saldırı Hızı", c.atk_speed),
                       ("Hasar Direnci", c.armor), ("Kaçınma", c.dodge), ("Can Çalma", c.lifesteal)] {
            if v != 0.0 {
                out.push((k, pct(v)));
            }
        }
        if c.regen > 0.0 {
            out.push(("Can Yenilenmesi", format!("×{:.0}", 1.0 + c.regen)));
        }
        out
    }

    /// Karakter kartı: her 25 kart bir seviye; ilk kart karakteri açar
    pub const CHAR_CARDS_PER_LEVEL: u32 = 25;
    pub const CHAR_MAX_CARDS: u32 = 1 + 9 * CHAR_CARDS_PER_LEVEL;
    /// Kart açma (altın): 1 kart, 10 kart (%20 indirimli)
    pub const CHAR_PULL_ONE: u32 = 2500;
    pub const CHAR_PULL_TEN: u32 = 20000;
    /// Nadirliğe göre çıkma şansı (%) ve karakter en üst seviyedeyken kartın elmas karşılığı
    pub const CHAR_ODDS: [u32; 4] = [55, 28, 13, 4];
    pub const CHAR_DUPE_GEMS: [u32; 4] = [1, 3, 8, 20];
    /// Karakter görevi: o karakterle günde bu kadar zombi → o karakterin 1 kartı
    pub const CHAR_DAILY_KILLS: u32 = 40;

    pub fn char_level_of(cards: u32) -> u32 {
        if cards == 0 {
            0
        } else {
            (1 + (cards - 1) / CHAR_CARDS_PER_LEVEL).min(10)
        }
    }

    /// Nadirlik zarı (0-99) → karakter
    pub fn char_roll(r: u32) -> usize {
        let mut acc = 0;
        for (i, p) in CHAR_ODDS.iter().enumerate() {
            acc += p;
            if r < acc {
                return i;
            }
        }
        0
    }

    pub fn char_xp_to_next(level: u32) -> u32 {
        (200.0 * (level as f32).powf(1.5)).round() as u32
    }

