    pub const D_AREA: f32 = 7.0;

    pub fn m(v: f32) -> f32 {
        v * PX_PER_M
    }

    pub fn dir_from_vec(x: f32, y: f32) -> u8 {
        let mut a = x.atan2(y);
        if a < 0.0 {
            a += TAU;
        }
        ((a / FRAC_PI_4).round() as i32).rem_euclid(8) as u8
    }

    pub fn dir_vec(d: u8) -> (f32, f32) {
        let a = d as f32 * FRAC_PI_4;
        (a.sin(), a.cos())
    }

